#include <stdio.h>
#include <string.h>

#define MOD 1000000007LL
#define MAXK 200005

static long long dp[MAXK][3];
static char s[MAXK];

int main(void) {
    int N, K;
    if (scanf("%d %d", &N, &K) != 2) return 0;
    scanf("%s", s);

    /*
      State compression by number of color segments currently formed.
      Let j be the number of monochromatic segments in the painted prefix
      after processing some operations.

      dp[i][j_parity-like compressed?]
      Actually transitions depend only on whether the next painted interval:
        - starts in white or inside painted area
        - ends in white or inside painted area
      and these effects on segment count depend only on current count j.

      A standard simplification gives:
      For each operation, choosing a red interval can introduce:
        +1 segment if it is disjoint from painted area,
         0 if it extends one side,
        -1 if it bridges two painted components with same color effect impossible here?
      But because final answer depends only on colorings, not exact interval placements,
      the count reduces to counting ways to realize color strings with constraints:
        - 'r' may paint any interval, creating or merging red coverage freely
        - 'b' may paint only already painted interval, recoloring a contiguous painted block blue

      The reachable final colorings are exactly those whose segment-color sequence can be
      produced by processing s left to right, where:
        - 'r' can increase number of segments by 1 or keep it same
        - 'b' can keep number of segments same or decrease by 1
      with first operation always creating one red segment.

      More precisely, if current coloring has j colored segments:
        on 'r':
          choose interval inside one segment -> split/replace, increasing by 1
          or extend existing / fill white, keeping j or creating first segment.
        on 'b':
          since no white allowed, interval must lie within colored area:
          recoloring inside one segment keeps j,
          spanning across a boundary can reduce j by 1.
      This yields DP:
        red:   ndp[j] += dp[j] + dp[j-1]
        blue:  ndp[j] += dp[j] + dp[j+1]
      Start with 0 segments.
      Final answer is sum over j<=N with parity/length feasibility enforced by segment count <= N.
    */

    memset(dp, 0, sizeof(dp));
    dp[0][0] = 1;

    // We'll use only dp[cur][j] via first index parity.
    for (int i = 0; i < K; i++) {
        int cur = i & 1;
        int nxt = cur ^ 1;
        for (int j = 0; j <= K + 1; j++) dp[nxt][j] = 0;

        if (s[i] == 'r') {
            for (int j = 1; j <= i + 1; j++) {
                long long val = dp[cur][j];
                if (val) {
                    dp[nxt][j] = (dp[nxt][j] + val) % MOD;
                    if (j + 1 <= K) dp[nxt][j + 1] = (dp[nxt][j + 1] + val) % MOD;
                }
            }
            // from 0 segments, red creates 1
            dp[nxt][1] = (dp[nxt][1] + dp[cur][0]) % MOD;
        } else { // 'b'
            for (int j = 1; j <= i; j++) {
                long long val = dp[cur][j];
                if (val) {
                    dp[nxt][j] = (dp[nxt][j] + val) % MOD;
                    if (j - 1 >= 1) dp[nxt][j - 1] = (dp[nxt][j - 1] + val) % MOD;
                }
            }
            // no transition from 0 on blue
        }
    }

    int last = K & 1;
    long long ans = 0;
    for (int j = 1; j <= N && j <= K; j++) {
        ans += dp[last][j];
        if (ans >= MOD) ans -= MOD;
    }

    printf("%lld\n", ans % MOD);
    return 0;
}

