#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    string s;
    cin >> N >> K >> s;

    // dp[i][j]:
    // after processing some prefix of operations,
    // i = number of painted balls,
    // j = number of red segments among painted balls.
    //
    // The painted prefix can be represented as a sequence of j red blocks
    // and some blue blocks, with total length i and all balls painted.
    //
    // Count number of different color sequences obtainable.
    //
    // Transition:
    // 'r': paint a contiguous white segment red.
    // This can:
    //   1) create a new red block (+1 red segment)
    //   2) extend/merge around existing blue structure in the painted prefix formulation
    //
    // A standard compressed DP for this process is:
    //   on 'r': ndp[i][j] = dp[i-1][j] * j + dp[i-1][j-1] * (i - j + 1)
    //   on 'b': ndp[i][j] = dp[i-1][j] * (j + 1) + dp[i-1][j] * (i - j)
    //
    // But simpler and correct formulation here:
    //
    // Let f[a][b] = number of strings of length a with exactly b red segments.
    // This is C(a+1, 2b) in combinatorics, but we do not need it directly.
    //
    // We process operations by counting how many balls are painted after each step.
    // Any operation paints a non-empty segment, so total painted count increases.
    //
    // Define dp[x][y]:
    // after processed operations, among first x balls of final painted set,
    // there are y red segments realizable.
    //
    // Transition by operation type:
    // - adding a red segment means choosing a non-empty gap among y blue-separated positions,
    //   equivalent recurrence below.
    // - adding a blue segment means choosing a non-empty already fully painted interval,
    //   which in final-string counting corresponds to increasing length while not increasing red segments.
    //
    // The following recurrence counts exactly the number of final color strings
    // obtainable after the sequence of operations:
    //
    // For 'r':
    //   ndp[i][j] += sum_{t < i} dp[t][j-1] * (i - t)
    // For 'b':
    //   ndp[i][j] += sum_{t < i} dp[t][j] * (i - t - 1 + j + 1)
    //
    // This can be simplified to a much cleaner interpretation:
    //
    // A final coloring is obtainable iff its maximal monochromatic segments can be grouped
    // into K ordered batches matching s, where each batch color is s[k], and each batch
    // consists of one or more monochromatic segments of that color created over time.
    //
    // Equivalent DP:
    // Build final string left to right by segments.
    // Let runs be monochromatic segments in final string.
    // Each operation contributes one or more final runs, but colors of runs created by the same
    // operation equal operation color. Since later paints can split previous segments,
    // the only invariant is:
    //   every final red run must be assigned to one of the 'r' operations,
    //   every final blue run to one of the 'b' operations,
    // and assignments must be surjective in operation order preserving within each color.
    //
    // This reduces to:
    // count binary strings of length N such that
    // number of red runs <= count('r') and number of blue runs <= count('b'),
    // with both counts positive only if corresponding color appears.
    //
    // More precisely, every operation paints a non-empty segment, so each operation must create
    // at least one final run of its color. Thus:
    //   red_runs >= #r_ops? No, one operation can be completely overwritten later, creating 0 final runs.
    // So only upper bounds remain.
    //
    // Therefore answer = number of binary strings of length N with:
    //   red_runs <= R and blue_runs <= B
    // where R = count('r'), B = count('b').
    //
    // For a binary string:
    // if it starts with red:
    //   red_runs = ceil(total_runs/2), blue_runs = floor(total_runs/2)
    // if starts with blue: vice versa.
    //
    // Number of strings of length N with exactly t runs is 2 * C(N-1, t-1) for t>=1, except N=0.
    // We filter by the run bounds depending on starting color.
    //
    // Let's count directly by choosing t and start color.

    int R = 0, B = 0;
    for (char c : s) {
        if (c == 'r') R++;
        else B++;
    }

    vector<vector<long long>> C(N + 1, vector<long long>(N + 1, 0));
    for (int i = 0; i <= N; i++) {
        C[i][0] = C[i][i] = 1;
        for (int j = 1; j < i; j++) {
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD;
        }
    }

    long long ans = 0;

    // All-white final state impossible since every operation paints non-empty segment.
    // So final string has at least 1 run.
    for (int t = 1; t <= N; t++) {
        long long waysRuns = C[N - 1][t - 1];

        // starts with red
        int redRuns = (t + 1) / 2;
        int blueRuns = t / 2;
        if (redRuns <= R && blueRuns <= B) {
            ans = (ans + waysRuns) % MOD;
        }

        // starts with blue
        redRuns = t / 2;
        blueRuns = (t + 1) / 2;
        if (redRuns <= R && blueRuns <= B) {
            ans = (ans + waysRuns) % MOD;
        }
    }

    cout << ans % MOD << '\n';
    return 0;
}

