def solve():
    import sys
    input = sys.stdin.readline

    N, K = map(int, input().split())
    s = input().strip()

    # dp[i][c] = number of ways to color first i balls ending with color c
    # c: 0 = white, 1 = red, 2 = blue
    dp = [[0] * 3 for _ in range(N + 1)]
    dp[0][0] = 1  # empty prefix, all white

    for idx, op in enumerate(s):
        new_dp = [[0] * 3 for _ in range(N + 1)]
        if op == 'r':
            # paint contiguous segment red
            for i in range(N + 1):
                for c in range(3):
                    if dp[i][c] == 0:
                        continue
                    # option: don't paint anything new
                    new_dp[i][c] = (new_dp[i][c] + dp[i][c]) % MOD
            # paint some segment ending at j
            for i in range(N):
                for c in range(3):
                    if dp[i][c] == 0:
                        continue
                    # start painting red from i+1 to j
                    for j in range(i + 1, N + 1):
                        new_dp[j][1] = (new_dp[j][1] + dp[i][c]) % MOD
        else:  # 'b'
            for i in range(N + 1):
                for c in range(3):
                    if dp[i][c] == 0:
                        continue
                    # option: don't paint
                    new_dp[i][c] = (new_dp[i][c] + dp[i][c]) % MOD
            # paint blue: must paint on non-white segment
            for i in range(N):
                for c in [1, 2]:  # only red or blue segment allowed before blue
                    if dp[i][c] == 0:
                        continue
                    for j in range(i + 1, N + 1):
                        new_dp[j][2] = (new_dp[j][2] + dp[i][c]) % MOD
        dp = new_dp

    ans = sum(dp[N]) % MOD
    print(ans)

