import java.util.Scanner;

public class Main {
    static final int MOD = 1_000_000_007;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int K = sc.nextInt();
        String s = sc.next();
        sc.close();

        // dp[w] = number of ways when we have w white balls left
        // Initially all are white, so dp[N] = 1
        long[] dp = new long[N + 1];
        dp[N] = 1;

        for (int i = 0; i < K; i++) {
            char op = s.charAt(i);
            long[] ndp = new long[N + 1];
            if (op == 'r') {
                // paint red: choose a segment of length len (1..w) from white part
                for (int w = 1; w <= N; w++) {
                    if (dp[w] == 0) continue;
                    long ways = dp[w];
                    // prefix sums for faster transition
                    // number of ways to choose starting position: (w - len + 1)
                    // So for each len, add (w - len + 1) * ways
                    for (int len = 1; len <= w; len++) {
                        int nw = w - len;
                        ndp[nw] = (ndp[nw] + ways * (w - len + 1)) % MOD;
                    }
                }
            } else {
                // paint blue: choose a segment from already colored (non-white) balls
                // colored count = N - w
                for (int w = 0; w <= N; w++) {
                    if (dp[w] == 0) continue;
                    int colored = N - w;
                    if (colored == 0) continue; // no colored balls to paint blue
                    long ways = dp[w];
                    for (int len = 1; len <= colored; len++) {
                        // number of starting positions in colored segment: (colored - len + 1)
                        ndp[w] = (ndp[w] + ways * (colored - len + 1)) % MOD;
                    }
                }
            }
            dp = ndp;
        }

        long ans = 0;
        for (int w = 0; w <= N; w++) {
            ans = (ans + dp[w]) % MOD;
        }
        System.out.println(ans);
    }
}

