import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        String s = fs.next();

        int K = s.length();

        // dp[i][j]:
        // after processing first i operations,
        // among the first painted prefix, exactly j balls are blue at the end.
        //
        // Key observation:
        // After any number of operations, painted balls always form a prefix [1..m].
        // A red operation can extend the prefix by any positive amount.
        // A blue operation can recolor any contiguous subsegment fully inside the painted prefix,
        // so it can only increase the count of blue balls from j to any t where j <= t <= current prefix length.
        //
        // We can compress by counting final colorings:
        // Let f[i][j] = number of ways after i operations to obtain a painted prefix of length m
        // with j blue balls, summed over all possible m.
        //
        // More directly, maintain dp over number of blue balls and total painted length implicitly.
        // Better formulation:
        // Let dp[len][blue] be number of ways to get painted prefix length len with blue count blue.
        // Transitions:
        //  - 'r': choose any segment of white balls adjacent to current prefix, i.e. extend len to any nlen > len,
        //         newly painted balls are red => blue unchanged.
        //  - 'b': choose any contiguous segment inside [1..len] containing no white balls automatically true,
        //         repaint it blue, so blue count increases from blue to any value up to len.
        //
        // O(N^2 K) is too big if N large, so optimize with prefix sums.
        //
        // We'll use dp[len][blue].
        long[][] dp = new long[N + 1][N + 1];
        dp[0][0] = 1;

        for (int idx = 0; idx < K; idx++) {
            char c = s.charAt(idx);
            long[][] ndp = new long[N + 1][N + 1];

            if (c == 'r') {
                // From (len, blue), can go to any nlen in [len+1..N], blue unchanged.
                for (int blue = 0; blue <= N; blue++) {
                    long run = 0;
                    for (int len = 0; len <= N; len++) {
                        run += dp[len][blue];
                        if (run >= MOD) run -= MOD;
                        // ndp[len'][blue] gets sum of dp[old][blue] for old < len'
                    }
                    // Simpler direct prefix on old len:
                    long pref = 0;
                    for (int nlen = 1; nlen <= N; nlen++) {
                        pref += dp[nlen - 1][blue];
                        if (pref >= MOD) pref -= MOD;
                        ndp[nlen][blue] = pref;
                    }
                }
            } else { // 'b'
                // From (len, blue), can increase blue to any nblue in [blue..len].
                for (int len = 0; len <= N; len++) {
                    long pref = 0;
                    for (int nblue = 0; nblue <= len; nblue++) {
                        pref += dp[len][nblue];
                        if (pref >= MOD) pref -= MOD;
                    }
                    // Need suffix sums actually:
                    long suffix = 0;
                    for (int blue = len; blue >= 0; blue--) {
                        suffix += dp[len][blue];
                        if (suffix >= MOD) suffix -= MOD;
                        ndp[len][blue] = suffix;
                    }
                    // But ndp[len][nblue] should be sum dp[len][blue] for blue <= nblue.
                    long sum = 0;
                    for (int nblue = 0; nblue <= len; nblue++) {
                        sum += dp[len][nblue];
                        if (sum >= MOD) sum -= MOD;
                        ndp[len][nblue] = sum;
                    }
                }
            }

            dp = ndp;
        }

        long ans = 0;
        for (int len = 0; len <= N; len++) {
            for (int blue = 0; blue <= len; blue++) {
                ans += dp[len][blue];
                if (ans >= MOD) ans -= MOD;
            }
        }

        System.out.println(ans % MOD);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}
